import os,pathlib,subprocess,shlex,re,json,hashlib
unit='km3-rt-controller.service'
def run(args):
 r=subprocess.run(args,capture_output=True,text=True)
 if r.returncode: print(json.dumps({'inner_command':args,'rc':r.returncode,'stderr':r.stderr}))
 return r.stdout.strip()
def clean_args(args):
 out=[]; i=0
 flags={'--enable-sync','--require-config','--require-realtime','--validate-config-only'}
 vals={'--config','--period-us','--duration-s'}
 while i<len(args):
  a=args[i]
  if i==0: out.append(a)
  elif a in flags: out.append(a)
  elif a in vals and i+1<len(args):
   v=args[i+1]
   out.extend([a,v if (a=='--config' and v.startswith('/')) or (a!='--config' and re.fullmatch(r'[0-9]+',v)) else '<redacted>']);i+=1
  else: out.append('<unrecognized-argument-redacted>')
  i+=1
 return out
pid_s=run(['systemctl','show',unit,'--property=MainPID','--value'])
print('MainPID='+pid_s)
raw=run(['systemctl','show',unit,'--property=ExecStart','--value'])
m=re.search(r'argv\[\]=(.*?)(?: ; ignore_errors=| ; start_time=| })',raw)
print('ExecStart.filtered='+json.dumps(clean_args(shlex.split(m.group(1))) if m else ['<format-unparsed-redacted>']))
pid=int(pid_s); root=pathlib.Path('/proc')/str(pid)
args=[x.decode(errors='replace') for x in (root/'cmdline').read_bytes().split(b'\0') if x]
print('argv.filtered='+json.dumps(clean_args(args)))
print('argv.enable_sync='+str('--enable-sync' in args))
print('exe='+os.readlink(root/'exe'))
print('exe.sha256='+hashlib.sha256((root/'exe').read_bytes()).hexdigest())
sockets=[]
for f in sorted((root/'fd').iterdir(),key=lambda x:int(x.name)):
 try: link=os.readlink(f)
 except FileNotFoundError: continue
 if link.startswith(('socket:[','pipe:[','anon_inode:')) or link in ('/dev/null','/dev/console'):
  print('fd.'+f.name+'='+link)
 else: print('fd.'+f.name+'=<filesystem-path-redacted>')
 if link.startswith('socket:['): sockets.append(link[8:-1])
for inode in sockets:
 types=[]
 for table in ('unix','tcp','tcp6','udp','udp6','raw','raw6','packet','netlink'):
